  ["_FightingDojoBlackbelt2EndBattleText"] = "\nSchiedsrichter!\v1 Punkt!",
  ["_FightingDojoBlackbelt3AfterBattleText"] = "Die einzige\nSache, vor der\vwir uns fürchten,\vist PSYCHOKINESE!",
