  ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "Hast Du schon\nBILL getroffen?\fEr ist mein\nEnkel!\fSchon als kleines\nKind hat er gerne\valles Mögliche\vgesammelt!",
  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "Der Wärter der\nSAFARI-ZONE ist\vsehr alt! Aber er\vist noch immer im\vDienst!\fAllerdings trägt\ner ein Gebiß!",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "BILL sammelt auf\nseinem PC Daten\vüber POKéMON!\fHat er sie Dir\ngezeigt?",
  ["_FuchsiaCityChanseySignText"] = "Name: CHANEIRA\fDieses POKéMON zu\nfangen ist reine\vGlückssache!",
  ["_FuchsiaCityErikText"] = "ERIK: Wo ist\nSARA? Ich wollte\vmich hier mit\vihr treffen!",
  ["_FuchsiaCityFossilSignKabutoText"] = "Name: KABUTO\fEin POKéMON,\ndas aus einem\vFossil wieder-\verschaffen wurde.",
  ["_FuchsiaCityFossilSignOmanyteText"] = "Name: AMONITAS\fEin POKéMON,\ndas aus einem\vFossil wieder-\verschaffen wurde.",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "...",
  ["_FuchsiaCityGamblerText"] = "Vor dem Eingang\nzur SAFARI-ZONE\vbefindet sich ein\vZoo.\fDas SAFARI-SPIEL\nist ideal, um\vPOKéMON zu\vfangen.",
  ["_FuchsiaCityGymSignText"] = "FUCHSANIA CITY\nPKMN-ARENA\vARENALEITER: KOGA\fDer giftige\nNinja-Meister!",
  ["_FuchsiaCityKangaskhanSignText"] = "Name: KANGAMA\fEin POKéMON, das\nseinen Nachwuchs\vin einem Beutel\vam Bauch trägt.",
  ["_FuchsiaCityLaprasSignText"] = "Name: LAPRAS\fDer König\nder Meere!",
  ["_FuchsiaCityPokecenterGuyText"] = "Du studierst die\nPOKéMON?\vDann gehe in die\vSAFARI-ZONE.\fDort gibt es\nviele seltene\vPOKéMON.",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "SAFARI-SPIEL\nPOKéMON-FANGEN!",
  ["_FuchsiaCitySafariZoneSignText"] = "POKéMON-PARADIES\nSAFARI-ZONE",
  ["_FuchsiaCitySignText"] = "FUCHSANIA CITY\nDie Stadt der\vrosaroten Träume",
  ["_FuchsiaCitySlowpokeSignText"] = "Name: FLEGMON\fEin freundliches,\naber sehr lahmes\vPOKéMON.",
  ["_FuchsiaCityVoltorbSignText"] = "Name: VOLTOBAL\fDieses POKéMON\nähnelt einem\vPOKéBALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "SAFARI-ZONE\nHAUS DES WÄRTERS",
  ["_FuchsiaCityYoungster1Text"] = "Hast Du schon das\nSAFARI-SPIEL\vgespielt? Manche\vPOKéMON kann man\vnur dabei fangen!",
  ["_FuchsiaCityYoungster2Text"] = "Dieser Ball dort\nist tatsächlich\vein POKéMON?!",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Hallo, {PLAYER}!\fWie beißen die\nFische?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh nein!\fDu hast keinen\nPlatz mehr für\vmein Geschenk!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Klasse! Du bist\nmir sympathisch!\fNimm das hier\nund gehe angeln!\f{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Ich bin der\nältere Bruder des\vPROFIANGLERS!\fIch liebe\nden Angelsport!\fAngelst Du auch\ngerne?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh!\nDas ist schade!",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "Selbst wenn man\nsie besiegt hat,\vwirken die Ninjas\vnoch bedrohlich!",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Hey! Warte, Du\nChampion in spe!\fDie ARENA von\nFUCHSANIA CITY\vist voller\vunsichtbarer\vMauern!\fDu kannst KOGA\nsehen, ihn aber\vnicht erreichen!\fDu mußt nach\nLücken in den\vunsichtbaren\vMauern suchen!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Hahaha!\fEin Kind fordert\neinen Ninja-\vMeister zum\vKampf heraus?\fWie Du willst!\nErlebe eine Welt\vdes Schreckens,\vbevor ich Dich\vbesiege!\fAn meinen\nSchlaf- und Gift-\vAttacken sollst\vDu verzweifeln!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Wirkt das TOXIN\nerst einmal, dann\vleiden POKéMON\vumso mehr, je\vlänger der Kampf\vdauert!\fEin wahrer\nAlptraum für\vden Gegner!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Na sowas!\nDu bist ein\vwürdiger Kämpfer!\fIch reiche Dir\nden SEELENORDEN!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Nun, da Du Träger\ndes SEELENORDENS\vbist, wird die\vABWEHR Deiner\vPOKéMON steigen!\fFerner kannst Du\nSURFER nun auch\vaußerhalb von\vKämpfen nutzen!\fBitte nimm auch\ndieses Geschenk!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\fTM06 ist TOXIN!\fEs ist eine mehr\nals 400 Jahre\valte Technik!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Du hast keinen\nPlatz für dieses\vItem!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Du setzt Deine\nMuskeln mit\vKöpfchen ein!\vGute Strategie!",
  ["_FuchsiaGymRocker1BattleText"] = "Der Erfolg hängt\nnicht von der\vStärke Deiner\vPOKéMON ab!\fEs kommt auf\ndie Strategie an!\fIntelligenz\nobsiegt über\vrohe Kraft!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Was?\nAußerordentlich!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Ich muß noch eine\nMenge von KOGA,\vmeinem Ninja-\vMeister, lernen!",
  ["_FuchsiaGymRocker2BattleText"] = "Ich möchte\nspäter einmal ein\vNinja werden!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Ich\nhabe verloren!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Ich bevorzuge\nSchlaf- und Gift-\vAttacken. Ihre\vWirkung dauert\vauch nach dem\vKampf an!",
  ["_FuchsiaGymRocker3BattleText"] = "Kannst Du\ngegen meine\vSPEZIAL-Techniken\vbestehen?",
  ["_FuchsiaGymRocker3EndBattleText"] = "Du\nhast mich\vhereingelegt!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Ich bin schwer\nbeeindruckt!\fEin Tip: Taste\ndie unsichtbaren\vMauern nach\vDurchgängen ab!",
  ["_FuchsiaGymRocker4BattleText"] = "Bleib stehen!\fFrustrieren Dich\ndie unsichtbaren\vMauern?",
  ["_FuchsiaGymRocker4EndBattleText"] = "Oh! Er\nhat mich besiegt!",
  ["_FuchsiaGymRocker5AfterBattleText"] = "Ich muß noch\nviel lernen!",
  ["_FuchsiaGymRocker5BattleText"] = "Meister KOGA\nunterweist mich\vin der Kunst des\vNinja-Kampfes!\fDer Einsatz von\nPOKéMON ist eine\vsehr alte\vNinja-Tradition!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Autsch!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "Wo Licht ist, ist\nauch Schatten!\fLicht oder\nSchatten! Wähle\veinen Weg!",
  ["_FuchsiaGymRocker6BattleText"] = "KOGA ist der\nNachfahre einer\vReihe legendärer\vNinja-Kämpfer!\fWer sind Deine\nVorfahren?",
  ["_FuchsiaGymRocker6EndBattleText"] = "Ich\nhabe es\vvermasselt!",
  ["_FuchsiaMartCooltrainerFText"] = "Hast Du schon\neinmal X-TEMPO\vausprobiert?\vDein POKéMON\vwird dadurch im\vKampf schneller!",
  ["_FuchsiaMartMiddleAgedManText"] = "Du hast einen\nWimpel aus der\vSAFARI-ZONE?\fKein Programmheft\noder einen\vKalender?",
