  ["_PokemonTower7FRocket3EndBattleText"] = "Leg\nDich nicht mit\vdem TEAM ROCKET\van!",
  ["_PoliwagDexEntry"] = "Die kurzen Beine\ndieses POKéMON\nsind zum Laufen\fkaum geeignet. Es\nbewegt sich daher\nschwimmend fort.",
  ["_PoliwhirlDexEntry"] = "Dieses POKéMON\nkann im Wasser\nund auch an Land\fleben. An Land\nschwitzt es sich\nden Körper naß.",
  ["_PoliwrathDexEntry"] = "Dieses POKéMON\nist ein meister-\nhafter Schwimmer.\fSeine Techniken\nschlagen selbst\nOlympiasieger.",
  ["_PonytaDexEntry"] = "Die Hufe dieses\nPOKéMON sind\nzehnmal härter\fals Diamanten.\nSie trampeln\nalles nieder.",
  ["_PoofText"] = "schwupp!",
  ["_PorygonDexEntry"] = "PORYGON besteht\nkomplett aus\nComputerdaten.\fEs kann sich frei\nin virtuellen\nWelten bewegen.",
