  ["_PsyduckDexEntry"] = "Dieses POKéMON\nlullt Gegner mit\nhypnotisierendem\fBlick ein, bevor\nes PSYKRÄFTE\neinsetzt.",
  ["_PushStartText"] = "Drücke START,\num das MENÜ\vaufzurufen!",
