  ["_Route17Biker9AfterBattleText"] = "Das Gefälle macht\ndas Lenken sehr\vschwer!",
  ["_Route17Biker9BattleText"] = "Du besitzt ein\nschickes FAHRRAD!\vFährt es sich\vgut?",
  ["_Route17Biker9EndBattleText"] = "Mist!",
