  ["_UndergroundPathRoute6GirlText"] = "Schon viele Leute\nhaben Dinge auf\vdem TUNNELPFAD\vverloren.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Ich würde gerne\nnach PRISMANIA\vCITY in das große\vEinkaufszentrum\vgehen!\fAber dort laufen\nso viele seltsame\vGestalten herum.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Der TUNNELPFAD\nführt Dich unter\vSAFFRONIA CITY\vhindurch nach\vLAVANDIA.\fWenn Du nach\nAZURIA CITY\vmöchtest, mußt\vDu durch das Haus\vauf der anderen \vSeite gehen.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Möchtest Du in\nPRISMANIA CITY\veinkaufen gehen?\fDu mußt draußen\nnur den Weg nach\vWesten nehmen!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "In PRISMANIA CITY\ngab es einen\vUnterschlupf des\vTEAM ROCKET?",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Ein verschlafenes\nPOKéMON ist in\vPRISMANIA CITY\vaufgetaucht!",
  ["_UndergroundPathRoute8GirlText"] = "Das große\nEinkaufszentrum\vin PRISMANIA CITY\vhat eine riesige\vAuswahl!",
  ["_UnleashedEnergyText"] = "{USER}\nerzeugt Energie!",
  ["_UnusedBenchGuyText1"] = "Ich wünschte, ich\nkönnte POKéMON\vfangen...",
  ["_UnusedBenchGuyText2"] = "Nach all dem Spaß\nbin ich nun müde.",
  ["_UnusedBenchGuyText3"] = "Der Leiter der\nSILPH CO.\vversteckt sich in\vder SAFARI-ZONE.",
  ["_UnveiledGhostText"] = "Das SILPH SCOPE\nhat den GEIST\videntifiziert!",
  ["_UseNextMonText"] = "Nächstes POKéMON\neinsetzen?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} setzt\nden ZERSCHNEIDER\vein!",
  ["_UsedInsteadText"] = "stattdessen\v",
  ["_UsedMove1Text"] = "\nben. ",
  ["_UsedMove2Text"] = "\nben. ",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer}\nsetzt STÄRKE ein.",
  ["_VaporeonDexEntry"] = "Dieses POKéMON\nlebt nahe an\nGewässern. Seine\fSchwanzflosse\nähnelt der einer\nMeerjungfrau.",
  ["_VendingMachineText1"] = "Ein Automat! Zur\nAuswahl stehen:",
  ["_VendingMachineText4"] = "Ups, nicht genug\nGeld!",
  ["_VendingMachineText5"] = "Eine Flasche\n{RAM:wStringBuffer} liegt\vim Schacht!",
  ["_VendingMachineText6"] = "Du kannst keine\nweiteren Items\vtragen!",
  ["_VendingMachineText7"] = "Kein Durst!",
  ["_VenomothDexEntry"] = "Die bunte\nFlügelzeichnung\ndieses POKéMON\fdient als Warnung\nvor den Giften,\ndie es verwendet.",
  ["_VenonatDexEntry"] = "Dieses POKéMON\nlebt im Schatten\ngroßer Bäume.\fEs frißt Insekten\nund wird von\nLicht angezogen.",
  ["_VenusaurDexEntry"] = "Dieses POKéMON\nfolgt der Sonne.\nDie Pflanze auf\fseinem Rücken\nabsorbiert\nSolarenergie.",
  ["_VermilionCityBeautyText"] = "Wir sind sehr\numweltbewußt!\fWir haben gehört,\ndaß SLEIMA sich\vin giftigem Dreck\vwohlfühlt und\ventwickelt!",
  ["_VermilionCityGambler1DidYouSeeText"] = "Hast Du gesehen?\nDie M.S. ANNE\vankert im Hafen!",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "Die M.S.ANNE ist\nausgelaufen!\fSie wird in einem\nJahr wieder hier\vanlegen.",
  ["_VermilionCityGambler2Text"] = "Ich möchte auf\ndiesem Land\vbauen.\fMein POKéMON\nebnet den Boden!",
  ["_VermilionCityGymSignText"] = "ORANIA CITY\nPKMN-ARENA\vARENALEITER:\vMAJOR BOB\fDer blitzschnelle\nArenaleiter!",
  ["_VermilionCityHarborSignText"] = "HAFEN VON\nORANIA CITY",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\fEin MASCHOCK\nebnet das Land!",
  ["_VermilionCityMachopText"] = "MASCHOCK: Macho!\nMaschock!",
  ["_VermilionCityNoticeSignText"] = "ACHTUNG!\fROUTE 12 wird\nvon einem\vschlafenden\vPOKéMON\vblockiert.\fUmleitung: \nFELSTUNNEL nach\vLAVANDIA.\fPOLIZEI VON\nORANIA CITY",
  ["_VermilionCityPokemonFanClubSignText"] = "POKéMON-FANCLUB\nAlle POKéMON-Fans\vsind willkommen!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Willkommen auf\nder M.S. ANNE!\fVerzeihung, hast\nDu ein Ticket?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} zeigt\ndas BOOTSTICKET!\fGroßartig!\nWillkommen auf\vder M.S. ANNE!",
  ["_VermilionCitySailor1ShipSetSailText"] = "Das Schiff ist in\nSee gestochen!",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Willkommen auf\nder M.S. ANNE!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} hat \nkein BOOTSTICKET!\fTut mir leid!\fDu brauchst ein\nTicket, um an\vBord gehen zu\vkönnen.",
  ["_VermilionCitySailor2Text"] = "Die M.S. ANNE ist\nein luxuriöses\vKreuzfahrtschiff.\fWir besuchen\nORANIA CITY\veinmal im Jahr.",
  ["_VermilionCitySignText"] = "ORANIA CITY\nDie Hafenstadt\vder einmaligen\vSonnenuntergänge!",
  ["_VermilionGymGentlemanAfterBattleText"] = "Die Tür öffnet\nsich nicht?\fMAJOR BOB war\nimmer sehr\vvorsichtig!",
  ["_VermilionGymGentlemanBattleText"] = "MAJOR BOB war\nmein Ausbilder!",
  ["_VermilionGymGentlemanEndBattleText"] = "Stop!\nDu bist zu gut!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Puh! Ein\nelektrisierender\vKampf!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Hey! Warte, Du\nChampion in spe!\fMAJOR BOB hat\neinen Spitznamen.\vMan nennt ihn den\vBLITZSCHNELLEN\vARENALEITER!\fEr ist ein\nExperte für\vELEKTRO-POKéMON!\fVOGEL- und\nWASSER-POKéMON\vsind ihm hilflos\vausgeliefert! Er\vnutzt auch gern\vPARALYSE!\fMAJOR BOB ist\nsehr vorsichtig!\fDu mußt ein\nRätsel lösen, um\vihn zu treffen!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Ich gebe Dir noch\neinen Tip, Junge!\fDie Elektrizität\nist enorm\vkraftvoll!\fDoch sie hat\nkeine Wirkung auf\vBODEN-POKéMON!",
  ["_VermilionGymLTSurgePreBattleText"] = "Hey, Kleiner!\nWas hast Du hier\vverloren?\fIm Kampf hast\nDu keine große\vChance, so viel\vist sicher!\fLaß mich Dir\netwas erzählen: \vWährend der\vPOKéMON-FELDZÜGE\vhaben mich meine\vELEKTRO-POKéMON\vgerettet!\fSie haben meine\nGegner mit Strom\vparalysiert!\fDas gleiche steht\nDir nun bevor!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Wow!\fDu weißt, wie man\nkämpft, Kleiner!\fAls Auszeichnung\nverleihe ich Dir\vden DONNERORDEN!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Dein Rucksack\nist voll!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "Der DONNERORDEN\nerhöht die\vINITIATIVE Deiner\vPOKéMON!\fAußerdem können\nDeine POKéMON nun\vjederzeit FLIEGEN\veinsetzen!\fDu bist ein\nbesonderer Junge!\vNimm das hier!",
  ["_VermilionGymSailorAfterBattleText"] = "MAJOR BOB hat\ndie Tür doppelt\vabgesichert!\fEin Tip? Der\nzweite Schalter\vbefindet sich\vdirekt neben dem\versten!",
  ["_VermilionGymSailorBattleText"] = "Das hier ist\nkein Spielplatz!",
  ["_VermilionGymSailorEndBattleText"] = "Wow!\nDu hast mich\vüberrascht!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, ich rede!\fMAJOR BOB hat\nhier irgendwo\vSchalter\vversteckt!",
  ["_VermilionGymSuperNerdBattleText"] = "Ich bin ein\nFliegengewicht,\vaber im Umgang\vmit Elektrizität\vbin ich Profi!",
  ["_VermilionGymSuperNerdEndBattleText"] = "Ein\nKurzschluß!",
  ["_VermilionGymTrashFailText"] = "Nichts! Hier ist\nnur Abfall...\vHey! Das Schloß\vwurde wieder\vverriegelt!",
  ["_VermilionGymTrashSuccessText1"] = "Hey! Hier ist ein\nHebel versteckt!\vIch werde ihn\vbetätigen!\fDas erste Schloß\nwurde entriegelt!",
  ["_VermilionGymTrashSuccessText2"] = "Hier ist noch ein\nHebel unter dem\vAbfall versteckt!\vIch betätige ihn!",
  ["_VermilionGymTrashSuccessText3"] = "Das zweite Schloß\nwurde entriegelt!\fDie mechanische\nTür hat sich\vgeöffnet!",
  ["_VermilionGymTrashText"] = "Hier ist nichts,\nbloß Abfall.",
  ["_VermilionMartCooltrainerFText"] = "POKéMON können\ngut oder böse\vsein. Das hängt\vganz von ihrem\vTrainer ab!",
  ["_VermilionMartCooltrainerMText"] = "Es gibt böse\nMenschen, die\vPOKéMON für\vVerbrechen\vmißbrauchen.\fDas TEAM ROCKET\nmacht mit\vseltenen POKéMON\vGeschäfte.\fDie POKéMON, die\nihrer Meinung\vnach nicht selten\vgenug sind,\vwerden von\vihnen ausgesetzt.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Ich bin der\nPROFIANGLER!\fIch liebe den\nAngelsport!\fAngelst Du auch\ngerne?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\fAngeln ist meine\nLeidenschaft!\fSuche in Seen\nund Flüssen und\vlande den großen\vFang!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Hallo, {PLAYER}!\fWie beißen die\nFische?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh nein!\fDu hast keinen\nPlatz für mein\vGeschenk!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Klasse! Du bist\nmir sympathisch!\fNimm das hier\nund gehe angeln,\vjunger Freund!\f{PLAYER} erhält\neine {RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Das ist\nwirklich schade!",
  ["_VermilionPidgeyHouseLetterText"] = "Liebe NIKKI! Ich\nhoffe, wir sehen\vuns bald wieder!\fWie ich höre,\nstiftet das TEAM\vROCKET in\vSAFFRONIA CITY\vUnruhe!\fIn ORANIA CITY\nscheint es sicher\vzu sein.",
  ["_VermilionPidgeyHousePidgeyText"] = "TAUBSI: Taubsi!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Ich lasse TAUBSI\neinen Brief nach\vSAFFRONIA CITY im\vNorden bringen!",
  ["_VermilionPokecenterFishingGuruText"] = "Auch wenn sie den\ngleichen Level\vhaben, können die\vFähigkeiten von\vPOKéMON trotzdem\vverschieden sein.\fDas POKéMON eines\nTrainers ist\vstärker als ein\vwildlebendes.",
  ["_VermilionPokecenterGuyText"] = "Es stimmt, daß\nein POKéMON mit\veinem hohen Level\vsehr stark ist...\fAllerdings haben\nalle POKéMON\vSchwächen. Die\vrichtige Attacke\vkann sie leicht\vbesiegen!\fDaher gibt es\nkein Universal-\vPOKéMON.",
  ["_VermilionPokecenterSailorText"] = "Mein POKéMON\nwurde vergiftet!\vDas Gift hat es\vlange nach dem\vKampf besiegt!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Dabei wollte ich\nnie verlieren!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Glaubst Du etwa,\nDu kannst es mit\vmir aufnehmen?",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Ich\nbin raus!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Ich muß gestehen,\nDu bist besser!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Ich glaube, Du\nbist gut! Gut\vgenug, um mich\vzu schlagen?",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Immerhin\nhatte ich eine\vChance!",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Du beschreitest\ndie SIEGESSTRASSE\vnicht ohne Grund!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Komm nur her!\nIch werde Dich\vbesiegen!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Auweia!\nIch bin besiegt!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Wenn Du nicht\nvorankommst,\vversuche , die\vFelsen zu\vverschieben!",
  ["_VictoryRoad2FHikerBattleText"] = "Die SIEGESSTRASSE\nstellt eine Art\vAbschlußprüfung\vfür Trainer dar!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Ahh! ",
  ["_VictoryRoad2FMoltresBattleText"] = "Jauuul!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "Auch {RIVAL}\nkam hier vorbei!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Du möchtest also\ndie TOP VIER\vherausfordern?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Voll\nerwischt!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Und wenn schon...\nDafür übersteigt\vmein Wissen über\vPOKéMON Deines\vbei weitem!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Wenn Du an mir\nvorbeikommst,\vkannst Du zu den\vTOP VIER gehen!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "Nein!\nUnglaublich!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Schon viele\nTrainer haben\vhier aufgegeben!",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "Die SIEGESSTRASSE\nist sehr schwer\vzu meistern!",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Gut\ngemacht!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Du hast mich in\ndie Schranken\vgewiesen!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Gleich siehst Du,\nwie gut Du bist!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Das\ndarf doch nicht\vwahr sein! Grrr!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Je härter die\nKämpfe sind,\vdesto stärker\vwirst Du!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Trainer sind\ngeborene Kämpfer,\vimmer auf der\vSuche nach\vstarken Gegnern!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Cool!\nDu bist wirklich\vstark!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Hast Du wirklich\nGIOVANNI vom\vTEAM ROCKET\vbesiegt?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Man erzählt von\neinem Wunderkind!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Du bist\ndas Wunderkind!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Die Trainer hier\nsind auf dem Weg\vzur PKMN-Liga!\vSei vorsichtig!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Nur Auserwählte\ndürfen passieren!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Ich\nfasse es nicht!",
  ["_VictreebelDexEntry"] = "Dieses POKéMON\nsoll in großen\nKolonien tief im\fDschungel leben,\ndoch niemand kann\ndies bestätigen.",
  ["_VileplumeDexEntry"] = "Je größer die\nBlütenblätter,\ndesto mehr\fgiftige Pollen\nsind in der Blüte\nenthalten.",
  ["_ViridianBlackboardBurnText"] = "Eine Verbrennung\nvermindert Kraft\vund Stärke. Die\vKP sinken stetig.\fVerbrennungen\ndauern auch nach\veinem Kampf an.\fMan heilt sie mit\nFEUERHEILER.",
  ["_ViridianBlackboardFrozenText"] = "Ein eingefrorenes\nPOKéMON ist\vbewegungsunfähig.\fEs behält auch\nnach dem Kampf\vdiesen Zustand\vbei.\fNur der EISHEILER\nkann es wieder\vauftauen!",
  ["_ViridianBlackboardPoisonText"] = "Ein vergiftetes\nPOKéMON verliert\vstetig KP.\fDie Wirkung des\nGiftes hält auch\vnach einem Kampf\van.\fGEGENGIFT heilt\nVergiftungen.",
  ["_ViridianBlackboardPrlzText"] = "Ein paralysiertes\nPOKéMON\vverliert an\vTreffgenauigkeit!\fDie Paralyse hält\nauch nach einem\vKampf an.\fMan behandelt sie\nmit PARA-HEILER.",
  ["_ViridianBlackboardSleepText"] = "Wenn ein POKéMON\nschläft, kann es\vnicht angreifen!\fEin schlafendes\nPOKéMON wacht\vauch nach dem\vKampf nicht auf.\fBenutze\nAUFWECKER, damit\ves aufwacht.",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} erhält\nTM42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "TM42 ist\nTRAUMFRESSER!",
  ["_ViridianCityFisherTM42NoRoomText"] = "Du trägst zuviele\nItems bei Dir!",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Diese PKMN-ARENA\nist stets\vgeschlossen!\fIch frage mich,\nwer hier wohl\vder ARENALEITER\vsein mag?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Der ARENALEITER\nvon VERTANIA CITY\vist zurück!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Großvater! Sei\nnicht so gemein!\vEr hatte noch\vkeinen Kaffee!!!",
  ["_ViridianCityGirlWhenIGoShopText"] = "Wenn ich zum\nEinkaufen nach\vMARMORIA CITY\vmöchte, muß ich\vimmer durch den\vVERTANIA-WALD\vgehen.",
  ["_ViridianCityGymLockedText"] = "Die Türen der\nARENA sind\vverschlossen...",
  ["_ViridianCityGymSignText"] = "VERTANIA CITY\nPKMN-ARENA",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, ich habe\nendlich meinen\vKaffee bekommen!\fNatürlich kannst\nDu passieren!\fHast Du es\netwa eilig?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Aha, Du benutzt\neinen POKéDEX!\fWenn Du ein \nPOKéMON fängst,\vwird Dein POKéDEX\vautomatisch\vaktualisiert.\fWas? Du weißt\nnicht, wie man\vPOKéMON fängt?\fKein Problem! Ich\nerkläre es Dir!",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Du kannst hier\nnicht durch!\fDas ist ein\nPrivatgelände!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Zeit ist Geld...\nDann gehe weiter!",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Willst Du ein\nPOKéMON fangen,\vmußt Du es\vzuerst schwächen!",
  ["_ViridianCityPokecenterGuyText"] = "Im PKMN-CENTER\nkannst Du müde,\vverletzte und\vbesiegte POKéMON\vheilen!",
  ["_ViridianCitySignText"] = "VERTANIA CITY\nDas immergrüne\vParadies!",
  ["_ViridianCityTrainerTips1Text"] = "TIPS FÜR TRAINER\fFange POKéMON,\num Deine Sammlung\vzu erweitern!\fJe mehr Du\nbesitzt, desto\vleichter werden\vdie Kämpfe!",
  ["_ViridianCityTrainerTips2Text"] = "TIPS FÜR TRAINER\fDie Attacken der\nPOKéMON werden\vdurch ihre\vANGRIFFSPUNKTE, \vAP, limitiert.\fUm die AP wieder\naufzufüllen, mußt\vDu die POKéMON\vin ein POKéMON-\vCENTER bringen!",
  ["_ViridianCityYoungster1Text"] = "Diese POKéBÄLLE\nan Deinem Gürtel\vzeigen mir, daß\vDu POKéMON\vbesitzt!\fEs ist klasse,\ndaß man jederzeit\vPOKéMON tragen\vund einsetzen\vkann, nicht wahr?",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Möchtest Du etwas\nüber die zwei\vRAUPEN-POKéMON\verfahren?",
  ["_ViridianForestLeavingSignText"] = "AUF WIEDERSEHEN\nIM VERTANIA-WALD.\fDER NÄCHSTE ORT\nIST MARMORIA\vCITY.",
  ["_ViridianForestNorthGateGrampsText"] = "Achte auf Büsche\nam Wegesrand.\fPOKéMON können\nsie mit einer\vSpezial-Technik\vkleinhacken.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Viele POKéMON\nleben in Höhlen\vund Wäldern.\fDu solltest Dich\nüberall umsehen,\vum verschiedene\vzu finden!",
  ["_ViridianForestSouthGateGirlText"] = "Du gehst in den\nVERTANIA-WALD?\vSei auf der Hut,\vdort verläuft man\vsich leicht!",
  ["_ViridianForestSouthGateLittleGirlText"] = "Hast Du schon\nein RATTFRATZ\vgefangen? Es ist\vklein, aber sein\vBiß ist heftig!",
  ["_ViridianForestTrainerTips1Text"] = "TIPS FÜR TRAINER\fWenn Du Kämpfe\nmeiden möchtest,\vbleibe hohem\vGras fern!",
  ["_ViridianForestTrainerTips2Text"] = "TIPS FÜR TRAINER\fDu kannst Deinen\nPOKéDEX jederzeit\vvon PROF. EICH\vvia PC bewerten\vlassen!",
  ["_ViridianForestTrainerTips3Text"] = "TIPS FÜR TRAINER\fEs ist verboten,\nanderen Trainern\vPOKéMON zu\vstehlen! Fang nur\vwilde POKéMON!",
  ["_ViridianForestTrainerTips4Text"] = "TIPS FÜR TRAINER\fGeschwächte\nPOKéMON sind\vleichter zu\vfangen!\fSind sie bei\nKräften, könnten\vsie fliehen!",
  ["_ViridianForestUseAntidoteSignText"] = "Bei Vergiftungen\nhat sich das\vGEGENGIFT aus dem\vPKMN-SUPERMARKT\vbewährt.",
  ["_ViridianForestYoungster1Text"] = "Meine Freunde und\nich haben Dich\vschon erwartet...\fUnsere POKéMON\nwollen kämpfen!!!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Psst! Sei leise!\nDu verjagst\valle Käfer...",
  ["_ViridianForestYoungster2BattleText"] = "Hey! Du hast auch\nPOKéMON! Los!\vLaß uns kämpfen!",
  ["_ViridianForestYoungster2EndBattleText"] = "Ah!\nRAUPY hat es\vnicht geschafft!",
  ["_ViridianForestYoungster3AfterBattleText"] = "So ein Mist! Ich\nmuß ein paar\vStärkere fangen!",
  ["_ViridianForestYoungster3BattleText"] = "Hey! Ein POKéMON-\nTrainer stiehlt\vsich nicht so\veinfach davon!!!",
  ["_ViridianForestYoungster3EndBattleText"] = "Oh!\nIch habe kein\vkampfbereites\vPOKéMON mehr!",
  ["_ViridianForestYoungster4AfterBattleText"] = "Mit ein bißchen\nGlück findet man\vunterwegs Items!\fIch muß hier\nirgendwo etwas\vverloren haben...",
  ["_ViridianForestYoungster4BattleText"] = "Hey, warte mal!\nWarum die Eile?",
  ["_ViridianForestYoungster4EndBattleText"] = "Uff!\nDu bist zu gut!\vIch gebe auf!",
  ["_ViridianForestYoungster5Text"] = "Verdammt!\nMir sind die\vPOKéBÄLLE\vausgegangen!\fWie fange ich nun\nbloß POKéMON?\fDu solltest immer\ngenug POKéBÄLLE\vbei Dir haben!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Du mußt stark\nsein, um unserem\vARENALEITER\ventgegenzutreten!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Hehe! So langsam\ngeht Dir die Luft\vaus!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Mir\ngehen die\vPOKéMON aus!!!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Der Meister wird\nmich schelten!",
  ["_ViridianGymCooltrainerM2BattleText"] = "Der Stil zeichnet\neinen großen\vKämpfer aus!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "\nIch habe den\vHalt verloren!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Du kannst nur in\ndie PKMN-LIGA,\vwenn Du unseren\vARENALEITER\vbesiegst!",
  ["_ViridianGymCooltrainerM3BattleText"] = "Die ARENAHALLE\nvon VERTANIA CITY\vwar lange Zeit\vgeschlossen, doch\vnun ist der\vMEISTER zurück!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Ich\nwurde besiegt?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "Als Träger des\nERDORDENS  werden\vDir alle POKéMON\vjeglichen Levels\vgehorchen!\fEr stellt den\nBeweis Deines\vKönnens als\vPOKéMON-TRAINER\vdar!\fAußerdem gewährt\ner Dir den Zugang\vzur PKMN-LIGA!\fNimm dieses\nGeschenk mit in\vDein PKMN-LIGA-\vAbenteuer!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Ich habe meinen\nMeister gefunden!\vMeine Taten waren\vschlecht... Ich\vlöse das\vTEAM ROCKET auf!\fVon nun an widme\nich mein Leben\vdem Studium der\vPOKéMON!\fVielleicht sehen\nwir uns eines\vTages wieder!\vLebe wohl!",
  ["_ViridianGymGiovanniPreBattleText"] = "Haha! Willkommen\nin meinem\vGeheimversteck!\fHier wollte ich\ndas TEAM ROCKET\vwiederauferstehen\vlassen!\fAber Du hast\nmich schon wieder\vaufgespürt!\vAlso gut! Dieses\vMal kenne ich\vkeine Gnade!\fIch, GIOVANNI,\nder größte aller\vTrainer, fordere\vRevanche!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha!\nDer Kampf war\vhart, aber fair!\vDu hast gewonnen!\vNimm bitte den\vERDORDEN zum\vZeichen meiner\vAnerkennung!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} erhält\nTM27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\fTM27 ist\nGEOFISSUR!\vMan kann damit\vein POKéMON\vmit nur einem\vTreffer besiegen!\fIch habe sie vor\nlanger Zeit\vgeschaffen, als\vich hier noch\vARENALEITER war.",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Du kannst sie\nmomentan nicht\vtragen!",
  ["_ViridianGymGuidePostBattleText"] = "Das gibt's nicht!\nGIOVANNI war\vhier ARENALEITER?",
  ["_ViridianGymGuidePreBattleText"] = "Hey! Warte, Du\nChampion in spe!\fNicht einmal ich\nkenne die\vIdentität des\vARENALEITERS von\vVERTANIA CITY!\fSoweit ich weiß,\nist er von allen\vARENALEITERN der\vgefährlichste!\fDie Trainer hier\nsetzen gerne\vBODEN-POKéMON\vein!",
  ["_ViridianGymHiker1AfterBattleText"] = "Ich bin Deiner\nGnade unwürdig!",
  ["_ViridianGymHiker1BattleText"] = "Kiai! Mit diesem\nKampfschrei\vmobilisiere ich\vmeine Kräfte!",
  ["_ViridianGymHiker1EndBattleText"] = "\nMeister, verzeih\vmir!",
  ["_ViridianGymHiker2AfterBattleText"] = "Ach, wären meine\nPOKéMON doch auch\vso starke\vKarateka wie ich!",
  ["_ViridianGymHiker2BattleText"] = "Karate ist die\nKönigsdisziplin\vdes Kampfsports!",
  ["_ViridianGymHiker2EndBattleText"] = "Au!",
  ["_ViridianGymHiker3AfterBattleText"] = "Du willst in die\nPKMN-LIGA? Du?\vWerde bloß nicht\vgrößenwahnsinnig!",
  ["_ViridianGymHiker3BattleText"] = "Ich bin der\nKARATE-KÖNIG!\vIch besiegle\vDein Schicksal!",
  ["_ViridianGymHiker3EndBattleText"] = "Ahh!",
  ["_ViridianGymRocker1AfterBattleText"] = "Kennst Du die\nIdentität unseres\vARENALEITERS?",
  ["_ViridianGymRocker1BattleText"] = "Ich bilde mit\nmeinen POKéMON\veine Einheit\vwie Yin und Yang!",
  ["_ViridianGymRocker1EndBattleText"] = "\nDeine POKéMON\vharmonieren gut\vmit Dir!",
  ["_ViridianGymRocker2AfterBattleText"] = "Warte nur!\nDafür wirst Du\vnoch büßen!",
  ["_ViridianGymRocker2BattleText"] = "Allein mein\nAnblick läßt\vDeine POKéMON\vschaudern!",
  ["_ViridianGymRocker2EndBattleText"] = "\nSie kringeln sich\vvor Lachen! NEIN!",
  ["_ViridianMartClerkParcelQuestText"] = "PROF. EICH\nschickt Dich,\voder?\fSeine Bestellung\nist angekommen!\vHolst Du das\vPaket für ihn ab?\f{PLAYER} erhält\nEICHS PAKET!",
  ["_ViridianMartClerkSayHiToOakText"] = "OK! Grüße PROF.\nEICH von mir!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Hey! Kommst Du\naus ALABASTIA?",
  ["_ViridianMartCooltrainerMText"] = "Tut mir leid!\nAlle TRÄNKE sind\vausverkauft!",
  ["_ViridianMartYoungsterText"] = "Dieser Laden\nführt viele\vGEGENGIFTE.",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Es macht Spaß,\nsich Spitznamen\vauszudenken. Aber\ves erfordert viel\vEinfallsreichtum!\fEinfache Namen\nkann man sich\vleichter merken!",
  ["_ViridianNicknameHouseLittleGirlText"] = "Mein Papa mag\nPOKéMON auch\vsehr gerne!",
  ["_ViridianNicknameHouseSpearowText"] = "WILLI: \nHabi! Habitak!",
  ["_ViridianNicknameHouseSpearySignText"] = "HABITAK\nSpitzname: WILLI",
  ["_ViridianPokecenterCooltrainerMText"] = "Es gibt in jeder\nStadt ein\vPKMN-CENTER.\fDort behandelt\nman Deine POKéMON\vkostenlos!",
  ["_ViridianPokecenterGentlemanText"] = "Du kannst den PC\nin der Ecke dort\vdrüben benutzen!\fDarauf hat man\nmich am Empfang\vfreundlicherweise\vhingewiesen.",
  ["_ViridianSchoolBlackboardText1"] = "Die Tafel zeigt\nStatuswechsel der\vPOKéMON während\vdes Kampfes an.",
  ["_ViridianSchoolBlackboardText2"] = "Wähle bitte ein\nThemengebiet aus.",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Puh! Ich\nversuche, meine\vNotizen auswendig\vzu lernen.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "OK!\fLies sorgfältig\nden Text auf der\vTafel!",
  ["_ViridianSchoolNotebookText1"] = "Du schaust in\ndas Notizbuch!\fErste Seite...\fZum Fangen von\nPOKéMON benutzt\vman POKéBÄLLE.\fMan kann bis zu\nsechs POKéMON auf\veinmal tragen.\fPOKéMON-TRAINER\nziehen POKéMON\vgroß und\vtrainieren sie.",
  ["_ViridianSchoolNotebookText2"] = "Zweite Seite...\fEin POKéMON bei\nvoller Stärke ist\vschwer zu fangen!\vMan sollte es\verst schwächen.\fFeuer, Gift und\nandere Attacken\vwirken Wunder!",
  ["_ViridianSchoolNotebookText3"] = "Dritte Seite...\fPOKéMON-TRAINER\nsuchen einander\vund lassen ihre\vPOKéMON kämpfen.\fIn den\nPKMN-ARENEN\vfinden stets\vKämpfe statt.",
  ["_ViridianSchoolNotebookText4"] = "Vierte Seite...\fDas Ziel jedes\nPOKéMON-TRAINERS\vist es, die acht\vLeiter der\vPKMN-ARENEN\vzu besiegen.\fNur dann darf er\nden TOP VIER in\vder PKMN-LIGA\vgegenübertreten!",
  ["_ViridianSchoolNotebookText5"] = "MÄDCHEN: Hey! Laß\ndie Finger von\vmeinen Notizen!",
  ["_VitaminNoEffectText"] = "Das würde keinen\nEffekt haben.",
  ["_VitaminStatRoseText"] = "{RAM:wNameBuffer}s\n{RAM:wStringBuffer} ist\vgestiegen.",
  ["_VoltorbDexEntry"] = "Dieses POKéMON\nwird oftmals mit\neinem POKéBALL\fverwechselt. Es\nlebt vorwiegend\nin Kraftwerken.",
  ["_VulpixDexEntry"] = "Dieses POKéMON\nhat bei seiner\nGeburt nur einen\fSchweif, der sich\nmit zunehmendem\nAlter aufspaltet.",
  ["_WannaTrade1Text"] = "Ich suche nach\n{RAM:wInGameTradeGiveMonName}!\fTauschst Du es\ngegen {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade2Text"] = "Hallo! Willst Du\nDein {RAM:wInGameTradeGiveMonName}\fnicht gegen ein\n{RAM:wInGameTradeReceiveMonName}\ftauschen?",
  ["_WannaTrade3Text"] = "Besitzt Du ein\n{RAM:wInGameTradeGiveMonName}?\fWillst Du es\ngegen {RAM:wInGameTradeReceiveMonName}\ftauschen?",
  ["_WardensHouseDisplayMerchandiseText"] = "Alte POKéMON-\nSpielsachen.",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "Fotos von POKéMON\nund Fossilien.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} gibt\ndem WÄRTER die\vGOLDZÄHNE!",
  ["_WardensHouseWardenGibberish1Text"] = "WÄRTER: Hef faff\nheffee!\fHa lof ha feef ee\nhaffhe he. Heff\vhee fiee!",
  ["_WardensHouseWardenGibberish2Text"] = "Eff heffe fefe!\nEef  hafahi-fone!",
  ["_WardensHouseWardenGibberish3Text"] = "Ha? Hei heff heh\nha hef ee haheh!",
  ["_WardensHouseWardenHM04ExplanationText"] = "WÄRTER: VM04\nist STÄRKE!\fDamit lernen\nPOKéMON, Felsen\vzu verschieben,\vauch wenn sie\vnicht kämpfen!\fHast Du bereits\ndas GEHEIME HAUS\vin der SAFARI-\vZONE gefunden?\fMan gewinnt eine\nVM, wenn man es\vfindet!\fAngeblich handelt\nes sich bei der\vVM um SURFER.",
  ["_WardensHouseWardenHM04NoRoomText"] = "Dein Rucksack\nist zu voll!",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} erhält\n{RAM:wStringBuffer}!",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "\fDer WÄRTER setzt\ndas Gebiß ein!",
  ["_WardensHouseWardenThanksText"] = "WÄRTER: Danke,\nJunge! Niemand\vhat auch nur ein\vWort von mir\vverstanden!\fSo konnte ich\nnicht arbeiten.\vNimm das hier\vfür Deine Mühen.",
  ["_WarpToLastPokemonCenterText"] = "In das letzte\nPKMN-CENTER\vzurückkehren?",
  ["_WartortleDexEntry"] = "Dieses POKéMON\nlauert im Wasser\nauf Beute.\fDie Ohren dienen\nbeim Schwimmen\nzur Orientierung.",
  ["_WasBlownAwayText"] = "{TARGET}\nwurde weggeweht!",
